#!/bin/sh
# kube-vip static pod for the ReadyStack Kubernetes VM stack (install order: README.md in the install directory).
#
# Writes /etc/kubernetes/manifests/kube-vip.yaml on a control-plane node from kube-vip.yaml (next to this script,
# generated by `kube-vip manifest pod`: ARP, leader election, control plane only), with the four placeholders below
# filled in. Run as root on each control-plane node, in this order:
#
#   first control-plane node:
#     kube-vip-static-pod.sh first-node    BEFORE `kubeadm init --control-plane-endpoint ${KUBE_VIP_ADDRESS}:6443 ...`
#     kube-vip-static-pod.sh after-init    AFTER kubeadm init has finished
#   second and third control-plane nodes:
#     kube-vip-static-pod.sh join          BEFORE `kubeadm join ... --control-plane`
#
# Why first-node/after-init: since Kubernetes 1.29, kubeadm init writes admin.conf bound to the kubeadm:cluster-admins
# group, whose RBAC binding exists only once the API server is up, and the API server is reached through the VIP that
# kube-vip has to bring up first (it needs a Lease to become leader). On the first node kube-vip therefore reads
# /etc/kubernetes/super-admin.conf (system:masters) during init, and admin.conf afterwards: after-init switches the
# hostPath back, and the kubelet restarts the static pod. kubeadm join --control-plane writes admin.conf before it starts
# the kubelet, and the binding exists by then, so joining nodes use admin.conf from the start (kube-vip's own e2e does
# the same: super-admin.conf for node 0 only).
#
# kubeadm init's preflight checks only its own four manifests, so a kube-vip.yaml already in /etc/kubernetes/manifests
# is fine (cmd/kubeadm/app/preflight/checks.go, v1.36.6).
#
# Placeholders (environment variables, all required):
#   LOCAL_REGISTRY       the local registry host:port the nodes pull from
#   DIGEST_kubevip       sha256:... of readystack/kubevip:v1.3.1-CE-ubuntu24.04-r1
#   KUBE_VIP_ADDRESS     the control-plane virtual IP (controlPlaneEndpoint)
#   KUBE_VIP_INTERFACE   the node interface that carries it (the same name on every control-plane node)
set -eu
here=$(cd "$(dirname "$0")" && pwd)
TEMPLATE=${TEMPLATE:-$here/kube-vip.yaml}
MANIFEST=${MANIFEST:-/etc/kubernetes/manifests/kube-vip.yaml}
ADMIN=/etc/kubernetes/admin.conf
SUPER=/etc/kubernetes/super-admin.conf

usage() { sed -n '2,30p' "$0" >&2; exit 2; }

render() {   # $1: the kubeconfig the pod mounts
  for v in LOCAL_REGISTRY DIGEST_kubevip KUBE_VIP_ADDRESS KUBE_VIP_INTERFACE; do
    eval "val=\${$v:-}"
    [ -n "$val" ] || { echo "kube-vip-static-pod.sh: $v is not set" >&2; exit 1; }
    case "$val" in *[!A-Za-z0-9.:/_@-]*) echo "kube-vip-static-pod.sh: $v=$val has an unexpected character" >&2; exit 1;; esac
  done
  case "$DIGEST_kubevip" in sha256:????????????????????????????????????????????????????????????????) ;;
    *) echo "kube-vip-static-pod.sh: DIGEST_kubevip must be sha256:<64 hex>" >&2; exit 1;; esac
  [ -f "$TEMPLATE" ] || { echo "kube-vip-static-pod.sh: no template $TEMPLATE" >&2; exit 1; }
  mkdir -p "$(dirname "$MANIFEST")"
  tmp="$(dirname "$MANIFEST")/.kube-vip.yaml.tmp.$$"   # a dotfile: the kubelet reads every other file there as a pod
  sed -e "s|\${LOCAL_REGISTRY}|$LOCAL_REGISTRY|g" -e "s|\${DIGEST_kubevip}|$DIGEST_kubevip|g" \
      -e "s|\${KUBE_VIP_ADDRESS}|$KUBE_VIP_ADDRESS|g" -e "s|\${KUBE_VIP_INTERFACE}|$KUBE_VIP_INTERFACE|g" \
      -e "s|^\( *\)path: $ADMIN\$|\1path: $1|" "$TEMPLATE" > "$tmp"
  if grep -q '\${' "$tmp"; then echo "kube-vip-static-pod.sh: unfilled placeholder in $TEMPLATE" >&2; rm -f "$tmp"; exit 1; fi
  grep -q "^ *path: $1\$" "$tmp" || { echo "kube-vip-static-pod.sh: the template has no hostPath $ADMIN" >&2; rm -f "$tmp"; exit 1; }
  chmod 0600 "$tmp" && mv "$tmp" "$MANIFEST"
  echo "wrote $MANIFEST (kubeconfig $1)"
}

case "${1:-}" in
  first-node) render "$SUPER" ;;
  join)       render "$ADMIN" ;;
  after-init)
    [ -f "$MANIFEST" ] || { echo "kube-vip-static-pod.sh: no $MANIFEST: run first-node before kubeadm init" >&2; exit 1; }
    [ -f "$ADMIN" ] || { echo "kube-vip-static-pod.sh: no $ADMIN: has kubeadm init finished?" >&2; exit 1; }
    tmp="$(dirname "$MANIFEST")/.kube-vip.yaml.tmp.$$"   # a dotfile: the kubelet reads every other file there as a pod
    sed "s|^\( *\)path: $SUPER\$|\1path: $ADMIN|" "$MANIFEST" > "$tmp"
    grep -q "^ *path: $ADMIN\$" "$tmp" || { echo "kube-vip-static-pod.sh: $MANIFEST mounts neither kubeconfig" >&2; rm -f "$tmp"; exit 1; }
    chmod 0600 "$tmp" && mv "$tmp" "$MANIFEST"
    echo "switched $MANIFEST to $ADMIN; the kubelet restarts kube-vip" ;;
  *) usage ;;
esac
